import {useState} from 'react'
import {Accordion} from '@github-ui/accordion'
import {Heading, Link} from '@primer/react'

export type CodeQualitySettingsFaqProps = {
  configureCodeCoverageDocsUrl: string
  openSourceRepoUrl: string
  coverageAgentEnabled?: boolean
}

export function CodeQualitySettingsFaq({
  configureCodeCoverageDocsUrl,
  openSourceRepoUrl,
  coverageAgentEnabled,
}: CodeQualitySettingsFaqProps) {
  const [expandedItems, setExpandedItems] = useState<string[]>(['faq-what-happens', 'faq-ai', 'faq-rules-languages'])

  return (
    <div className="d-flex flex-column gap-3 tmp-mt-6">
      <Heading as="h2" className="h3">
        Frequently asked questions
      </Heading>
      <Accordion expandedItems={expandedItems} onChange={setExpandedItems}>
        <div className="border-top color-border-default">
          <Accordion.Item value="faq-what-happens" className="border-bottom color-border-default py-2">
            <Accordion.Trigger>
              <span className="f4">What happens once I turn on code quality scanning?</span>
            </Accordion.Trigger>
            <Accordion.Content>
              <span className="color-fg-muted">
                GitHub will perform a point-in-time scan of the default branch of the repository, reporting back code
                quality findings and suggestions to developers. It will also proactively start scanning pull requests
                for code quality issues.{' '}
                {coverageAgentEnabled ? (
                  <span>
                    A pull request will also be opened to merge an AI-generated workflow YAML file that is needed to
                    enable code coverage analysis.
                  </span>
                ) : (
                  <>
                    To enable code coverage reports, you will need to manually commit a workflow file, once code quality
                    is enabled.{' '}
                    <Link href={configureCodeCoverageDocsUrl} inline target="_blank" rel="noopener noreferrer">
                      Learn how to configure code coverage
                    </Link>
                  </>
                )}
              </span>
            </Accordion.Content>
          </Accordion.Item>
          <Accordion.Item value="faq-ai" className="border-bottom color-border-default py-2">
            <Accordion.Trigger>
              <span className="f4">Does Code Quality use AI?</span>
            </Accordion.Trigger>
            <Accordion.Content>
              <span className="color-fg-muted">
                Along with standard findings that are detected using the default CodeQL query suite, Code Quality also
                uses AI to detect additional findings, labeled as AI findings.
                {coverageAgentEnabled && (
                  <span>
                    {' '}
                    Additionally, to enable code coverage analysis, a workflow YAML file is generated using AI that will
                    need to be reviewed and merged manually from the pull request that is opened.
                  </span>
                )}
              </span>
            </Accordion.Content>
          </Accordion.Item>
          <Accordion.Item value="faq-rules-languages" className="border-bottom color-border-default py-2">
            <Accordion.Trigger>
              <span className="f4">What quality rules and languages are supported?</span>
            </Accordion.Trigger>
            <Accordion.Content>
              <span className="color-fg-muted">
                We will support quality rules and languages found in this{' '}
                <Link href={openSourceRepoUrl} inline target="_blank" rel="noopener noreferrer">
                  open source repository
                </Link>
                . The languages supported with CodeQL for standard findings are: C#, Java, JavaScript/TypeScript,
                Python, Ruby, and Go. Other languages may be scanned with AI, but will not generate standard findings
                with CodeQL.
              </span>
            </Accordion.Content>
          </Accordion.Item>
        </div>
      </Accordion>
    </div>
  )
}
